def evaluate(input_data):
    tokens = []
    for line in input_data:
        tokens.extend(line.split())

    stack = []
    words = {}

    def require(count):
        if len(stack) < count:
            raise StackUnderflowError("Insufficient number of items in stack")

    def add():
        require(2)
        b = stack.pop()
        a = stack.pop()
        stack.append(a + b)

    def subtract():
        require(2)
        b = stack.pop()
        a = stack.pop()
        stack.append(a - b)

    def multiply():
        require(2)
        b = stack.pop()
        a = stack.pop()
        stack.append(a * b)

    def divide():
        require(2)
        b = stack.pop()
        a = stack.pop()
        if b == 0:
            raise ZeroDivisionError("divide by zero")
        quotient = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            quotient = -quotient
        stack.append(quotient)

    def dup():
        require(1)
        stack.append(stack[-1])

    def drop():
        require(1)
        stack.pop()

    def swap():
        require(2)
        stack[-1], stack[-2] = stack[-2], stack[-1]

    def over():
        require(2)
        stack.append(stack[-2])

    builtins = {
        "+": add,
        "-": subtract,
        "*": multiply,
        "/": divide,
        "dup": dup,
        "drop": drop,
        "swap": swap,
        "over": over,
    }

    def execute(body):
        for command in body:
            if isinstance(command, tuple):
                _, number = command
                stack.append(number)
            else:
                command()

    index = 0
    while index < len(tokens):
        token = tokens[index]
        lowered = token.lower()

        if token == ":":
            index += 1
            if index >= len(tokens):
                raise ValueError("illegal operation")
            name = tokens[index].lower()
            try:
                int(name)
            except ValueError:
                pass
            else:
                raise ValueError("illegal operation")

            body = []
            index += 1
            while index < len(tokens) and tokens[index] != ";":
                word = tokens[index].lower()
                if word in words:
                    body.extend(words[word])
                elif word in builtins:
                    body.append(builtins[word])
                else:
                    try:
                        number = int(word)
                    except ValueError:
                        raise ValueError("undefined operation")
                    body.append(("push", number))
                index += 1
            if index >= len(tokens) or tokens[index] != ";":
                raise ValueError("illegal operation")
            words[name] = body
            index += 1
            continue

        if lowered in words:
            execute(words[lowered])
        elif lowered in builtins:
            builtins[lowered]()
        else:
            try:
                number = int(lowered)
            except ValueError:
                raise ValueError("undefined operation")
            stack.append(number)
        index += 1

    return stack

