def _straight_high(ranks):
    unique = sorted(set(ranks))
    if len(unique) != 5:
        return None
    if unique[-1] - unique[0] == 4:
        return unique[-1]
    if unique == [2, 3, 4, 5, 14]:
        return 5
    return None


def _hand_key(hand):
    cards = hand.split()
    ranks = [_RANKS[card[:-1]] for card in cards]
    suits = [card[-1] for card in cards]

    flush = len(set(suits)) == 1
    high_straight = _straight_high(ranks)
    straight = high_straight is not None
    counts = Counter(ranks)
    by_count = {}
    for rank, count in counts.items():
        by_count.setdefault(count, []).append(rank)

    if straight and flush:
        return (8, (high_straight,))

    if 4 in by_count:
        quad = by_count[4][0]
        kicker = by_count[1][0]
        return (7, (quad, kicker))

    if 3 in by_count and 2 in by_count:
        return (6, (by_count[3][0], by_count[2][0]))

    if flush:
        return (5, tuple(sorted(ranks, reverse=True)))

    if straight:
        return (4, (high_straight,))

    if 3 in by_count:
        triple = by_count[3][0]
        kickers = tuple(sorted(by_count[1], reverse=True))
        return (3, (triple,) + kickers)

    if len(by_count.get(2, [])) == 2:
        pairs = sorted(by_count[2], reverse=True)
        kicker = by_count[1][0]
        return (2, (pairs[0], pairs[1], kicker))

    if 2 in by_count:
        pair = by_count[2][0]
        kickers = tuple(sorted(by_count[1], reverse=True))
        return (1, (pair,) + kickers)

    return (0, tuple(sorted(ranks, reverse=True)))


def best_hands(hands):
    if not hands:
        return []
    keyed = [(_hand_key(hand), hand) for hand in hands]
    best = max(key for key, _ in keyed)
    return [hand for key, hand in keyed if key == best]

