from collections import defaultdict


def can_chain(dominoes):
    if not dominoes:
        return []

    adjacency = defaultdict(list)
    for index, (left, right) in enumerate(dominoes):
        adjacency[left].append((right, index))
        adjacency[right].append((left, index))

    if any(len(edges) % 2 for edges in adjacency.values()):
        return None

    used = [False] * len(dominoes)
    vertices = []

    def visit(vertex):
        while adjacency[vertex]:
            neighbour, edge = adjacency[vertex].pop()
            if used[edge]:
                continue
            used[edge] = True
            visit(neighbour)
        vertices.append(vertex)

    visit(dominoes[0][0])

    if not all(used):
        return None

    vertices.reverse()
    return list(zip(vertices, vertices[1:]))

class BowlingGame:
    def __init__(self):
        self.rolls = []
        self.frame = 0
        self.frame_rolls = []
        self.game_over = False

    def roll(self, pins):
        if self.game_over:
            raise ValueError("Cannot roll after the game is over")
        if not isinstance(pins, int) or isinstance(pins, bool):
            raise ValueError("Pin count must be an integer")
        if pins < 0 or pins > 10:
            raise ValueError("Pin count must be between 0 and 10")

        if self.frame < 9:
            if not self.frame_rolls:
                self.frame_rolls.append(pins)
                if pins == 10:
                    self._finish_frame()
            else:
                if self.frame_rolls[0] + pins > 10:
                    raise ValueError("Frame score cannot exceed 10")
                self.frame_rolls.append(pins)
                self._finish_frame()
            self.rolls.append(pins)
            return

        # Tenth frame.
        if not self.frame_rolls:
            self.frame_rolls.append(pins)
        elif len(self.frame_rolls) == 1:
            first = self.frame_rolls[0]
            if first == 10:
                self.frame_rolls.append(pins)
            else:
                if first + pins > 10:
                    raise ValueError("Frame score cannot exceed 10")
                self.frame_rolls.append(pins)
                if first + pins < 10:
                    self.game_over = True
        elif len(self.frame_rolls) == 2:
            first, second = self.frame_rolls
            if first == 10:
                if second != 10 and second + pins > 10:
                    raise ValueError("Bonus rolls cannot exceed 10")
                self.frame_rolls.append(pins)
                self.game_over = True
            else:
                # A spare: exactly one bonus roll is allowed.
                self.frame_rolls.append(pins)
                self.game_over = True
        else:
            raise ValueError("Cannot roll after the game is over")

        self.rolls.append(pins)

    def _finish_frame(self):
        self.frame += 1
        self.frame_rolls = []

    def score(self):
        if not self.game_over:
            raise ValueError("Cannot score an incomplete game")

        total = 0
        index = 0
        for _ in range(10):
            if self.rolls[index] == 10:
                total += 10 + self.rolls[index + 1] + self.rolls[index + 2]
                index += 1
            elif self.rolls[index] + self.rolls[index + 1] == 10:
                total += 10 + self.rolls[index + 2]
                index += 2
            else:
                total += self.rolls[index] + self.rolls[index + 1]
                index += 2
        return total

import copy


class Zipper:
    def __init__(self, node, path=None):
        self._node = node
        self._path = path if path is not None else []

    @staticmethod
    def from_tree(tree):
        return Zipper(copy.deepcopy(tree))

    def value(self):
        return self._node["value"]

    def set_value(self, value):
        self._node["value"] = value
        return self

    def left(self):
        child = self._node.get("left")
        if child is None:
            return None
        return Zipper(child, self._path + [(self._node, "left")])

    def set_left(self, tree):
        self._node["left"] = tree
        return self

    def right(self):
        child = self._node.get("right")
        if child is None:
            return None
        return Zipper(child, self._path + [(self._node, "right")])

    def set_right(self, tree):
        self._node["right"] = tree
        return self

    def up(self):
        if not self._path:
            return None
        parent, _ = self._path[-1]
        return Zipper(parent, self._path[:-1])

    def to_tree(self):
        root = self._path[0][0] if self._path else self._node
        return copy.deepcopy(root)

from json import dumps


class Tree:
    def __init__(self, label, children=None):
        self.label = label
        self.children = children if children is not None else []

    def __dict__(self):
        return {self.label: [c.__dict__() for c in sorted(self.children)]}

    def __str__(self, indent=None):
        return dumps(self.__dict__(), indent=indent)

    def __lt__(self, other):
        return self.label < other.label

    def __eq__(self, other):
        return self.__dict__() == other.__dict__()

    def _parents(self):
        parents = {self: None}
        stack = [self]
        while stack:
            node = stack.pop()
            for child in node.children:
                parents[child] = node
                stack.append(child)
        return parents

    def _find(self, label):
        stack = [self]
        while stack:
            node = stack.pop()
            if node.label == label:
                return node
            stack.extend(node.children)
        return None

    def from_pov(self, from_node):
        target = self._find(from_node)
        if target is None:
            raise ValueError("Tree could not be reoriented")

        parents = self._parents()

        def reorient(node, came_from):
            neighbours = [child for child in node.children if child is not came_from]
            parent = parents.get(node)
            if parent is not None and parent is not came_from:
                neighbours.append(parent)
            return Tree(node.label, [reorient(n, node) for n in neighbours])

        return reorient(target, None)

    def path_to(self, from_node, to_node):
        source = self._find(from_node)
        if source is None:
            raise ValueError("Tree could not be reoriented")
        destination = self._find(to_node)
        if destination is None:
            raise ValueError("No path found")

        parents = self._parents()

        def ancestors(node):
            result = []
            while node is not None:
                result.append(node)
                node = parents.get(node)
            return result

        source_ancestors = ancestors(source)
        destination_ancestors = ancestors(destination)
        destination_set = set(destination_ancestors)

        common = None
        for node in source_ancestors:
            if node in destination_set:
                common = node
                break

        up = []
        for node in source_ancestors:
            up.append(node.label)
            if node is common:
                break

        down = []
        for node in destination_ancestors:
            if node is common:
                break
            down.append(node.label)

        return up + list(reversed(down))

